import sys

import numpy as np
import wgpu

SHADER = """
struct Params { n: u32, dt: f32, pad0: u32, pad1: u32 };

@group(0) @binding(0) var<storage, read_write> pos: array<vec2<f32>>;
@group(0) @binding(1) var<storage, read_write> vel: array<vec2<f32>>;
@group(0) @binding(2) var<storage, read_write> acc: array<vec2<f32>>;
@group(0) @binding(3) var<uniform> params: Params;

@compute @workgroup_size(64)
fn accelerate(@builtin(global_invocation_id) gid: vec3<u32>) {
    let i = gid.x;
    if (i >= params.n) { return; }
    let pi = pos[i];
    var a = vec2<f32>(0.0, 0.0);
    for (var j: u32 = 0u; j < params.n; j = j + 1u) {
        let d = pos[j] - pi;
        let r2 = dot(d, d) + 0.01;
        a = a + d / (r2 * sqrt(r2));
    }
    acc[i] = a;
}

@compute @workgroup_size(64)
fn integrate(@builtin(global_invocation_id) gid: vec3<u32>) {
    let i = gid.x;
    if (i >= params.n) { return; }
    let v = vel[i] + acc[i] * params.dt;
    vel[i] = v;
    pos[i] = pos[i] + v * params.dt;
}
"""


def read_input(path):
    with open(path) as f:
        tok = f.read().split()
    n = int(float(tok[0]))
    steps = int(float(tok[1]))
    dt = float(tok[2])
    data = np.array(tok[3:3 + 4 * n], dtype=np.float64).reshape(n, 4)
    return n, steps, dt, data


def simulate(n, steps, dt, data):
    pos = np.ascontiguousarray(data[:, 0:2], dtype=np.float32)
    vel = np.ascontiguousarray(data[:, 2:4], dtype=np.float32)
    if steps == 0:
        # Nothing to run on the GPU; particles stay where they were read.
        return pos, vel

    device = wgpu.utils.get_default_device()
    usage = wgpu.BufferUsage.STORAGE | wgpu.BufferUsage.COPY_SRC | wgpu.BufferUsage.COPY_DST
    pos_buf = device.create_buffer_with_data(data=pos, usage=usage)
    vel_buf = device.create_buffer_with_data(data=vel, usage=usage)
    acc_buf = device.create_buffer(size=n * 8, usage=usage)
    params = np.zeros(4, dtype=np.uint8).view(np.uint8)
    params = np.array([n, 0, 0, 0], dtype=np.uint32)
    params.view(np.float32)[1] = np.float32(dt)
    par_buf = device.create_buffer_with_data(
        data=params, usage=wgpu.BufferUsage.UNIFORM | wgpu.BufferUsage.COPY_DST
    )

    module = device.create_shader_module(code=SHADER)
    S = wgpu.BufferBindingType.storage
    entries = [
        {"binding": i, "visibility": wgpu.ShaderStage.COMPUTE, "buffer": {"type": S}}
        for i in range(3)
    ]
    entries.append({
        "binding": 3,
        "visibility": wgpu.ShaderStage.COMPUTE,
        "buffer": {"type": wgpu.BufferBindingType.uniform},
    })
    bgl = device.create_bind_group_layout(entries=entries)
    layout = device.create_pipeline_layout(bind_group_layouts=[bgl])
    bind = device.create_bind_group(layout=bgl, entries=[
        {"binding": i, "resource": {"buffer": b, "offset": 0, "size": b.size}}
        for i, b in enumerate([pos_buf, vel_buf, acc_buf, par_buf])
    ])
    p_acc = device.create_compute_pipeline(
        layout=layout, compute={"module": module, "entry_point": "accelerate"})
    p_int = device.create_compute_pipeline(
        layout=layout, compute={"module": module, "entry_point": "integrate"})

    groups = (n + 63) // 64
    enc = device.create_command_encoder()
    cp = enc.begin_compute_pass()
    cp.set_bind_group(0, bind)
    for _ in range(steps):
        cp.set_pipeline(p_acc)
        cp.dispatch_workgroups(groups)
        cp.set_pipeline(p_int)
        cp.dispatch_workgroups(groups)
    cp.end()
    device.queue.submit([enc.finish()])

    pos = np.frombuffer(device.queue.read_buffer(pos_buf), dtype=np.float32).reshape(n, 2)
    vel = np.frombuffer(device.queue.read_buffer(vel_buf), dtype=np.float32).reshape(n, 2)
    return pos.astype(np.float64), vel.astype(np.float64)


def summarize(pos, vel):
    pos = pos.astype(np.float64)
    vel = vel.astype(np.float64)
    c = pos.mean(axis=0)
    m = vel.sum(axis=0)
    ke = ((vel * vel).sum(axis=1) / 2).sum()
    spread = np.sqrt(((pos - c) ** 2).sum(axis=1).mean())
    return [
        f"CENTER {c[0]:.6f} {c[1]:.6f}",
        f"MOMENTUM {m[0]:.6f} {m[1]:.6f}",
        f"KINETIC {ke:.6f}",
        f"SPREAD {spread:.6f}",
    ]


def main():
    n, steps, dt, data = read_input(sys.argv[1])
    pos, vel = simulate(n, steps, dt, data)
    sys.stdout.write("\n".join(summarize(pos, vel)) + "\n")


if __name__ == "__main__":
    main()
